public class ClassPathComputer {
    public static String computeClassFilePath(String outputDir, String fqn) {
        String relative = fqn.replace('.', '/') + ".class";
        if (outputDir.endsWith("/")) return outputDir + relative;
        return outputDir + "/" + relative;
    }

    public static void main(String[] args) {
        System.out.println(computeClassFilePath("build/classes", "com.learnbyself.model.User"));
    }
}

