practiceProblems.solution:
public class AlignmentChecker {
    public static boolean isAligned(String filePath, String declaredPackage) {
        if (filePath == null || declaredPackage == null) return false;
        String normalized = filePath.replace('\\', '/');
        int lastSlash = normalized.lastIndexOf('/');
        if (lastSlash == -1) return declaredPackage.isEmpty();
        String dirPart = normalized.substring(0, lastSlash);
        String expectedDirSuffix = declaredPackage.replace('.', '/');
        return dirPart.endsWith(expectedDirSuffix);
    }

    public static void main(String[] args) {
        System.out.println(isAligned("src/com/learnbyself/app/Main.java", "com.learnbyself.app"));
        System.out.println(isAligned("src/utils/Helper.java", "com.learnbyself.utils"));
    }
}

