public class ClasspathAssembler {
    public static String assembleCp(String baseDir, String[] jars, String separator) {
        StringBuilder sb = new StringBuilder(baseDir);
        for (String jar : jars) {
            sb.append(separator).append("lib/").append(jar);
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        String[] libs = {"gson-2.10.jar", "junit-5.jar"};
        System.out.println(assembleCp("bin", libs, ":"));
    }
}

